def permitted_excerpts(permissions, global_permissions):
    return [row for row in EXCERPTS
            if ("*" in permissions or all(code in permissions for code in row.permissions))
            and (not row.global_permission or "*" in global_permissions or row.global_permission in global_permissions)]
